                    "key='" + key + '\'' +
                    ", value='" + value + '\'' +
                    '}';
        }
    }

    public static class UrlBuilder {
        private URL url;
        private Map<String, String> params;

        public UrlBuilder(URL url) {
            this.url = url;
            this.params = new HashMap<>();
